using System;

unsafe
{
    var x = new[] { 0, 1, 2 };
    int[]* xp = &x;
    var c = new C(xp);
    c.Print();
}

public unsafe class C
{
    private int[]* _x;

    public C(int[]* x)
    {
        _x = x;
    }

    public void Print()
    {
        int[] x = *_x;
        for (int i = 0; i < x.Length; i++)
        {
            Console.Write(x[i]);
        }
    }
}

